    private static void SourceOracles()
    {
        string startup = FixedText(StartupGzip, StartupSha, StartupBlob), form = FixedText(MainWindowGzip, MainWindowSha, MainWindowBlob);
        _ = FixedText(LicenseGzip, LicenseSha, LicenseBlob);
        Check("audit:225", startup.IndexOf("WaitingMutex(e)", StringComparison.Ordinal) <= startup.IndexOf("Settings.ImportLegacyPclPreferences()", StringComparison.Ordinal));
        Check("audit:226", startup.Contains("If Not UtilityCommand Then Settings.ImportLegacyPclPreferences()", StringComparison.Ordinal));
        Check("audit:228", !form.Contains("Settings.Set(\"CacheMsV2OAuthRefresh\", Settings.Get", StringComparison.Ordinal));
