    }
    private static string FixedText(string packed, string sha, string blob)
    {
        using MemoryStream input = new(Convert.FromBase64String(packed)); using GZipStream zip = new(input, CompressionMode.Decompress); using MemoryStream output = new(); zip.CopyTo(output);
        byte[] bytes = output.ToArray(); Native.Check(Convert.ToHexString(SHA256.HashData(bytes)).ToLowerInvariant() == sha, "Pinned f4 oracle SHA256 mismatch.");
        byte[] header = Encoding.ASCII.GetBytes("blob " + bytes.Length + "\0"); byte[] git = new byte[header.Length + bytes.Length]; header.CopyTo(git, 0); bytes.CopyTo(git, header.Length);
        Native.Check(Convert.ToHexString(SHA1.HashData(git)).ToLowerInvariant() == blob, "Pinned f4 oracle Git blob mismatch.");
        return new UTF8Encoding(false, true).GetString(bytes);
    }
